urlset:


  {{ site.url }}/
  1.0
  weekly


{% for post in site.posts %}

  {{ site.url }}{{ post.url }}
  0.7
  monthly
  {{ post.date | date_to_xmlschema }}

{% endfor %}

{% for page in site.pages %}
{% if page.url != "/404.html" and page.url != "/sitemap.xml" %}

  {{ site.url }}{{ page.url }}
  0.5
  yearly

{% endif %}
{% endfor %}
